CREATE PROCEDURE DA_DROP_TYPE(IN SCHEMANAME VARCHAR(100), IN TYPENAME VARCHAR(100)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCOUNT INTEGER;     SELECT COUNT(*) INTO ROWCOUNT FROM M_TABLES WHERE TABLE_NAME=:TYPENAME AND SCHEMA_NAME=:SCHEMANAME;     IF ROWCOUNT>0 THEN         EXECUTE IMMEDIATE 'DROP TYPE ' || :TYPENAME;     END IF; END
